={{
(() => {
  const registros = Array.isArray($json.movim) ? $json.movim : [];
  const cuenta = (($('Chat - Entrada').item.json.chatInput || '')
    .toUpperCase()
    .match(/\b[A-Z]{1,5}-\d{2,8}\b/) || [''])[0];

  const limpio = (v) => (v ?? '').toString().trim();

  const valor = (r, campos) => {
    for (const c of campos) {
      const v = limpio(r[c]);
      if (v) return v;
    }
    return "";
  };

  const dinero = (v) => {
    const n = Number(v);
    if (!Number.isFinite(n) || n === 0) return "";
    return "Q" + n.toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  };

  const mostrados = registros.slice(0, 10);

  const detalle = mostrados.map((r, i) => {
    const mov = valor(r, ["movim", "movimiento"]);
    const fecha = valor(r, ["fecha", "fecha_movim"]);
    const tipo = valor(r, ["tipo", "tipomovim", "tipo_movim", "documento", "movimiento_tipo"]);
    const totalRaw = valor(r, ["total", "monto", "importe", "calc_total", "total_movim"]);
    const total = dinero(totalRaw);

    const partes = [];
    if (mov) partes.push("Movimiento: " + mov);
    if (fecha) partes.push("Fecha: " + fecha);
    if (tipo) partes.push("Tipo: " + tipo);
    if (total) partes.push("Total: " + total);

    return (i + 1) + ". " + (partes.length ? partes.join(" | ") : "Registro de movimiento");
  }).join("\n");

  const totalRegistros = Number($json.totalRecordCount || registros.length);

  let respuesta =
    "Historial de movimientos consultado directamente en CAF Web:\n\n" +
    "🔹 Cuenta: " + cuenta + "\n" +
    "🔹 Registros reportados por CAF: " + totalRegistros + "\n\n" +
    detalle;

  if (registros.length > 10) {
    respuesta += "\n\nMostrando los primeros 10 registros devueltos por CAF.";
  }

  return respuesta;
})()
}}

