parameters.jsCode:
const input = $('Configuración CAF').item.json || {};
const mensajeOriginal = (input.chatInput || '').toString();
const mensaje = mensajeOriginal.trim();
const sessionId = (input.sessionId || input.session_id || input.webhookId || 'sesion-default').toString();

// Estado persistente leído desde la Data Table de n8n.
let estado = null;
try {
  if ($json && $json.state_json) estado = JSON.parse($json.state_json);
} catch (e) {}

if (!estado || typeof estado !== 'object') {
  estado = {
    active: false,
    phase: 'base',
    pendingField: '',
    draft: {
      cuenta_cliente: '',
      codigo_producto: '',
      cantidad: null,
      direccion_entrega: '',
      contacto: '',
      correo: '',
      telefono: ''
    },
    commercialApproved: false
  };
}

if (!estado.draft || typeof estado.draft !== 'object') estado.draft = {};
let draft = estado.draft;

const salida = (extra = {}) => ({
  ...input,
  ...extra,
  draft,
  sessionKeyCotizacion: sessionId,
  persist_session_id: sessionId,
  persist_state_json: JSON.stringify(estado)
});

const limpiar = v => (v ?? '').toString().trim();
const esSi = v => /^(si|sí|s|yes|incluye|incluido|con iva|iva incluido)$/i.test(limpiar(v));
const esNo = v => /^(no|n|sin iva|no incluye|excluye iva)$/i.test(limpiar(v));
const emailValido = v => {
  const m = limpiar(v).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return m ? m[0] : '';
};
const telefonoValido = v => {
  const m = limpiar(v).match(/\+?\d[\d\s().-]{6,}\d/);
  return m ? m[0].trim() : '';
};

const solicitaGenerarDocumento =
  /\b(aprobar|apruebo|aprobado|generar|genera|crear|crea|preparar|prepara|revisar|revisa)\b.*\b(cotizaci[oó]n|documento|pdf|word)\b/i.test(mensaje) ||
  /\b(pdf|word)\b.*\b(cotizaci[oó]n|documento)\b/i.test(mensaje);

// Si el usuario inicia explícitamente una cotización nueva con cliente, producto y cantidad,
// reinicia cualquier estado conversacional pendiente de una prueba anterior en la misma sesión.
const iniciaNuevaCotizacion =
  /\b(cotiz(?:ar|acion|ación|aciones)|presupuesto|proforma)\b/i.test(mensaje);
const cuentaNueva = (mensaje.toUpperCase().match(/\b[A-Z]{1,5}-\d{2,8}\b/) || [null])[0];
const codigosNuevos = mensaje.toUpperCase().match(/\b(?=[A-Z0-9-]*[A-Z])(?=[A-Z0-9-]*\d)[A-Z0-9-]{5,}\b/g) || [];
const codigoNuevo = codigosNuevos.find(x => x !== cuentaNueva && !/^[A-Z]{1,5}-\d{2,8}$/.test(x));
const cantidadNuevaMatch =
  mensaje.match(/(?:quiero\s+cotizar|necesito\s+cotizar|cotizar|cantidad(?:\s+de)?|cant(?:idad)?|necesito|quiero)\s*:?\s*(\d+(?:[.,]\d+)?)/i) ||
  mensaje.match(/\b(\d+(?:[.,]\d+)?)\s*(?:unidades?|uds?|piezas?)\b/i);

if (
  iniciaNuevaCotizacion &&
  cuentaNueva &&
  codigoNuevo &&
  cantidadNuevaMatch
) {
  estado = {
    active: false,
    phase: 'base',
    pendingField: '',
    draft: {
      cuenta_cliente: '',
      codigo_producto: '',
      cantidad: null,
      direccion_entrega: '',
      contacto: '',
      correo: '',
      telefono: ''
    },
    commercialApproved: false,
    lastCompleted: null
  };
  draft = estado.draft;
}

// -----------------------------------------------------------------------------
// REVISIÓN COMERCIAL PERSISTENTE
// -----------------------------------------------------------------------------
if (estado.phase === 'revision' && estado.pendingField && estado.lastCompleted) {
  const d = estado.lastCompleted;
  const item = Array.isArray(d.items) && d.items.length ? d.items[0] : {};
  const campo = estado.pendingField;
  let valido = true;
  let mensajeError = '';

  if (campo === 'iva') {
    if (esSi(mensaje)) {
      d.iva_estado = 'Incluye IVA 12%';
    } else if (esNo(mensaje)) {
      d.iva_estado = 'No incluye IVA 12%';
    } else {
      valido = false;
      mensajeError = 'No pude identificar la respuesta. Responde **Sí** si el precio incluye IVA 12% o **No** si no lo incluye.';
    }
  } else if (campo === 'pago') {
    if (/^usar\s+(caf|actual)$/i.test(mensaje)) {
      if (limpiar(d.condiciones_pago) && limpiar(d.condiciones_pago).toLowerCase() !== 'por confirmar') {
        // Conserva lo obtenido de CAF.
      } else {
        valido = false;
        mensajeError = 'CAF no tiene una condición de pago confirmada para este borrador. Indícame la condición final, por ejemplo: **Crédito 30 días** o **Contado**.';
      }
    } else if (mensaje.length >= 3) {
      d.condiciones_pago = mensaje;
    } else {
      valido = false;
      mensajeError = 'Indícame la condición de pago final, por ejemplo: **Crédito 30 días** o **Contado**.';
    }
  } else if (campo === 'entrega') {
    if (/^usar\s+(caf|actual)$/i.test(mensaje)) {
      const actual = limpiar(item.tiempo_entrega);
      if (actual && !/confirmar/i.test(actual)) {
        // Conserva el plazo actual.
      } else {
        valido = false;
        mensajeError = 'El plazo actual todavía requiere confirmación. Indícame el plazo comercial final, por ejemplo: **4 a 6 semanas**.';
      }
    } else if (mensaje.length >= 3) {
      item.tiempo_entrega = mensaje;
    } else {
      valido = false;
      mensajeError = 'Indícame el plazo de entrega final.';
    }
  } else if (campo === 'asesor_nombre') {
    if (mensaje.length >= 3) d.asesor = mensaje;
    else {
      valido = false;
      mensajeError = 'Indícame el nombre del asesor responsable.';
    }
  } else if (campo === 'asesor_telefono') {
    const tel = telefonoValido(mensaje);
    if (tel) d.telefono_asesor = tel;
    else {
      valido = false;
      mensajeError = 'El teléfono no parece válido. Escríbelo nuevamente, por ejemplo: **4707-0021**.';
    }
  } else if (campo === 'asesor_email') {
    const email = emailValido(mensaje);
    if (email) d.correo_asesor = email;
    else {
      valido = false;
      mensajeError = 'El correo no parece válido. Escríbelo en un formato como **asesor@praisa.com**.';
    }
  } else if (campo === 'cotizacion') {
    const numero = mensaje.replace(/^\s*(cotizaci[oó]n|numero|n[uú]mero|no\.?|#)\s*:?\s*/i, '').trim();
    if (numero.length >= 2) d.cotizacion = numero;
    else {
      valido = false;
      mensajeError = 'Indícame el número oficial de cotización, por ejemplo: **261603(A)**.';
    }
  }

  if (Array.isArray(d.items) && d.items.length) d.items[0] = item;
  estado.lastCompleted = d;

  if (!valido) {
    return [{
      json: salida({
        esCotizacion: true,
        generarDocumento: false,
        respuestaDirectaRevision: true,
        cotizacionCancelada: false,
        cotizacionLista: false,
        mensajeCotizacion: mensajeError
      })
    }];
  }

  const orden = ['iva', 'pago', 'entrega', 'asesor_nombre', 'asesor_telefono', 'asesor_email', 'cotizacion'];
  const idx = orden.indexOf(campo);
  const siguiente = idx >= 0 && idx < orden.length - 1 ? orden[idx + 1] : '';

  if (siguiente) {
    estado.pendingField = siguiente;

    let pregunta = '';
    if (siguiente === 'pago') {
      const actual = limpiar(d.condiciones_pago) || 'Por confirmar';
      pregunta =
        '✅ IVA registrado.\n\n' +
        `**Condiciones de pago actuales:** ${actual}\n` +
        'Escribe la condición final, por ejemplo **Crédito 30 días** o **Contado**. ' +
        'Si el dato de CAF es correcto, puedes escribir **usar CAF**.';
    } else if (siguiente === 'entrega') {
      const actual = limpiar(item.tiempo_entrega) || 'Por confirmar';
      pregunta =
        '✅ Condiciones de pago registradas.\n\n' +
        `**Entrega actual:** ${actual}\n` +
        'Indícame el plazo de entrega comercial final. Si el plazo actual ya está confirmado, puedes escribir **usar actual**.';
    } else if (siguiente === 'asesor_nombre') {
      pregunta = '✅ Plazo de entrega registrado.\n\n¿Cuál es el **nombre del asesor** responsable de esta cotización?';
    } else if (siguiente === 'asesor_telefono') {
      pregunta = 'Perfecto. Ahora indícame el **teléfono directo del asesor**.';
    } else if (siguiente === 'asesor_email') {
      pregunta = 'Gracias. Ahora indícame el **correo del asesor**.';
    } else if (siguiente === 'cotizacion') {
      pregunta =
        '✅ Datos del asesor registrados.\n\n' +
        'Por último, indícame el **número oficial de cotización** que debe aparecer en el documento. ' +
        'Ejemplo: **261603(A)**.';
    }

    return [{
      json: salida({
        esCotizacion: true,
        generarDocumento: false,
        respuestaDirectaRevision: true,
        cotizacionCancelada: false,
        cotizacionLista: false,
        mensajeCotizacion: pregunta
      })
    }];
  }

  // Final de revisión comercial.
  d.estado = 'APROBADA_PARA_GENERAR';
  d.nota_control = 'REVISIÓN COMERCIAL COMPLETADA. Revisión final antes de envío al cliente.';
  estado.lastCompleted = d;
  estado.phase = 'aprobada';
  estado.pendingField = '';
  estado.commercialApproved = true;

  const resumen =
    '✅ **Revisión comercial completada.**\n\n' +
    `- Cotización: ${limpiar(d.cotizacion)}\n` +
    `- IVA: ${limpiar(d.iva_estado)}\n` +
    `- Pago: ${limpiar(d.condiciones_pago)}\n` +
    `- Entrega: ${limpiar(d.items?.[0]?.tiempo_entrega)}\n` +
    `- Asesor: ${limpiar(d.asesor)}\n` +
    `- Teléfono asesor: ${limpiar(d.telefono_asesor)}\n` +
    `- Correo asesor: ${limpiar(d.correo_asesor)}\n\n` +
    'Si todo está correcto, escribe **Generar cotización** para crear Google Docs, PDF y Word.';

  return [{
    json: salida({
      esCotizacion: true,
      generarDocumento: false,
      respuestaDirectaRevision: true,
      cotizacionCancelada: false,
      cotizacionLista: false,
      datosDocumento: d,
      mensajeCotizacion: resumen
    })
  }];
}

// Si el usuario pide generar/aprobar y ya existe un borrador, primero pasa por revisión comercial.
if (solicitaGenerarDocumento) {
  if (estado.lastCompleted && typeof estado.lastCompleted === 'object') {
    if (estado.commercialApproved === true && estado.phase === 'aprobada') {
      return [{
        json: salida({
          esCotizacion: true,
          generarDocumento: true,
          respuestaDirectaRevision: false,
          cotizacionCancelada: false,
          cotizacionLista: true,
          datosDocumento: estado.lastCompleted,
          mensajeCotizacion: ''
        })
      }];
    }

    estado.phase = 'revision';
    estado.pendingField = 'iva';
    estado.commercialApproved = false;

    const d = estado.lastCompleted;
    const item = Array.isArray(d.items) && d.items.length ? d.items[0] : {};
    const precio = Number(item.precio_unitario_preliminar || 0).toLocaleString('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });

    return [{
      json: salida({
        esCotizacion: true,
        generarDocumento: false,
        respuestaDirectaRevision: true,
        cotizacionCancelada: false,
        cotizacionLista: false,
        datosDocumento: d,
        mensajeCotizacion:
          '🔎 **Iniciemos la revisión comercial antes de generar el documento.**\n\n' +
          `Precio unitario consultado en CAF: **Q${precio}**\n\n` +
          '¿Este precio **incluye IVA 12%**?\n\nResponde **Sí** o **No**.'
      })
    }];
  }

  return [{
    json: salida({
      esCotizacion: true,
      generarDocumento: false,
      respuestaDirectaRevision: true,
      cotizacionCancelada: false,
      cotizacionLista: false,
      faltantes: ['borrador de cotización'],
      mensajeCotizacion:
        'Todavía no tengo un borrador de cotización listo. Primero indícame el cliente, producto y cantidad que deseas cotizar.'
    })
  }];
}

const iniciaCotizacion =
  /\b(cotiz(?:ar|acion|ación|aciones|aciónes)|presupuesto|proforma)\b/i.test(mensaje) ||
  /\b(quiero|necesito|deseo|puedes|podrias|podrías)\b.*\b(oferta|cotiz)/i.test(mensaje);

const cancelar =
  estado.active &&
  /\b(cancelar|cancela|cancelémosla|cancelemosla|salir|detener)\b.*\b(cotiz|solicitud)?/i.test(mensaje);

const esCotizacion = Boolean(estado.active || iniciaCotizacion);

if (!esCotizacion) {
  return [{ json: salida({
    esCotizacion: false,
    generarDocumento: false,
    respuestaDirectaRevision: false,
    cotizacionCancelada: false,
    cotizacionLista: false
  }) }];
}

if (cancelar) {
  estado.active = false;
  estado.phase = 'base';
  estado.pendingField = '';
  estado.commercialApproved = false;
  estado.lastCompleted = null;
  estado.draft = {
    cuenta_cliente: '',
    codigo_producto: '',
    cantidad: null,
    direccion_entrega: '',
    contacto: '',
    correo: '',
    telefono: ''
  };

  return [{
    json: {
      ...input,
      esCotizacion: true,
      generarDocumento: false,
