const resp = $json || {};
const limpio = v => (v ?? '').toString().trim();

let registros = [];
const candidatosArray = [
  resp.prod,
  resp.productos,
  resp.data,
  resp.rows,
  resp.results,
  resp.items
];
for (const a of candidatosArray) {
  if (Array.isArray(a)) {
    registros = a;
    break;
  }
}
if (!registros.length) {
  for (const v of Object.values(resp)) {
    if (Array.isArray(v) && v.length && typeof v[0] === 'object') {
      registros = v;
      break;
    }
  }
}

const busqueda = limpio($('IA - Preparar búsqueda producto').item.json.text);
const originales = limpio($('Chat - Entrada').item.json.chatInput);

const normaliza = s => limpio(s)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toUpperCase()
  .replace(/[“”]/g, '"')
  .replace(/\s+/g, ' ')
  .trim();

const q = normaliza(busqueda);
const original = normaliza(originales);
const tokens = q.split(/\s+/).filter(t => t.length >= 2);

const familias = [
  ['BOLA', ['BOLA', 'BALL']],
  ['MARIPOSA', ['MARIPOSA', 'BUTTERFLY']],
  ['COMPUERTA', ['COMPUERTA', 'GATE']],
  ['GLOBO', ['GLOBO', 'GLOBE']],
  ['RETENCION', ['RETENCION', 'CHECK', 'NO RETORNO']],
  ['AGUJA', ['AGUJA', 'NEEDLE']],
  ['REGULADORA', ['REGULADORA', 'REGULADOR', 'PRV']],
  ['SEGURIDAD', ['SEGURIDAD', 'SAFETY']],
  ['TRAMPA', ['TRAMPA', 'TRAP']],
  ['MANOMETRO', ['MANOMETRO', 'PRESSURE GAUGE']]
];

let familiaSolicitada = null;
for (const [nombre, sinonimos] of familias) {
  if (sinonimos.some(s => q.includes(s) || original.includes(s))) {
    familiaSolicitada = {nombre, sinonimos};
    break;
  }
}

let conexionSolicitada = null;
if (/\bROSCAD[AO]\b|\bROSCA\b|\bNPT\b|\bBSP\b/.test(q + ' ' + original)) {
  conexionSolicitada = {nombre:'ROSCADA', sinonimos:['ROSCAD', 'ROSCA', 'NPT', 'BSP']};
} else if (/\bBRID[AO]\b|\bBRIDA\b|\bFLANGE\b/.test(q + ' ' + original)) {
  conexionSolicitada = {nombre:'BRIDA', sinonimos:['BRIDA', 'BRID', 'FLANGE']};
}

const servicioVapor = /\bVAPOR\b|\bSTEAM\b/.test(q + ' ' + original);
const sizeMatch = original.match(/\b(\d+(?:\s+\d+\/\d+|\/\d+)?)\s*(?:PULGADAS?|PULG|")/);
const tamanoSolicitado = sizeMatch ? sizeMatch[1].replace(/\s+/g,' ') : '';

const textoRegistro = r => normaliza([
  r.nombre_prod,
  r.descripcion,
  r.descrip,
  r.codpro,
  r.codigo_fabricante,
  r.categoria,
  r.marca
].filter(Boolean).join(' '));

const contieneTamano = (texto, tamano) => {
  if (!tamano) return false;
  const esc = tamano.replace(/[.*+?^$()|[\]\\]/g, '\\const contieneTamano = (texto, tamano) => {
  if (!tamano) return false;
  const esc = tamano.replace(/[.*+?^$()|[\]\\]/g, '\\$&');
  const re = new RegExp('(^|[^0-9])' + esc + '\\s*(?:"|PULG|NPT|BSP|BRIDA|FLANGE|$)');
  return re.test(texto);
};');
  // Evita falsos positivos: una solicitud de 2" no debe coincidir con 1/2" ni 1 1/2".
  const re = new RegExp('(^|[^0-9/])' + esc + '\\s*(?:"|PULG|NPT|BSP|BRIDA|FLANGE|$)');
  return re.test(texto);
};

const evalua = r => {
  const texto = textoRegistro(r);
  let score = 0;
  let familiaOk = !familiaSolicitada;
  let conexionOk = !conexionSolicitada;
  let tamanoOk = !tamanoSolicitado;
  let vaporOk = !servicioVapor;

  if (familiaSolicitada) {
    familiaOk = familiaSolicitada.sinonimos.some(s => texto.includes(s));
    if (familiaOk) score += 12;
  }
  if (conexionSolicitada) {
    conexionOk = conexionSolicitada.sinonimos.some(s => texto.includes(s));
    if (conexionOk) score += 6;
  }
  if (tamanoSolicitado) {
    tamanoOk = contieneTamano(texto, tamanoSolicitado);
    if (tamanoOk) score += 8;
  }
  if (servicioVapor) {
    vaporOk = texto.includes('VAPOR') || texto.includes('STEAM');
    if (vaporOk) score += 3;
  }

  for (const t of tokens) {
    if (/^\d+$/.test(t)) continue;
    if (texto.includes(t)) score += 1;
  }

  const esenciales = [familiaOk, conexionOk, tamanoOk];
  return {
    ...r,
    __score: score,
    __familiaOk: familiaOk,
    __conexionOk: conexionOk,
    __tamanoOk: tamanoOk,
    __vaporOk: vaporOk,
    __esencialesCumplidos: esenciales.filter(Boolean).length
  };
};

const evaluados = registros
  .map(evalua)
  .sort((a,b) => b.__esencialesCumplidos - a.__esencialesCumplidos || b.__score - a.__score);

let candidatos = evaluados;

if (familiaSolicitada) {
  const mismaFamilia = candidatos.filter(r => r.__familiaOk);
  candidatos = mismaFamilia.length ? mismaFamilia : [];
}

const exactos = candidatos.filter(r => r.__tamanoOk && r.__conexionOk);
if (exactos.length) candidatos = exactos;

candidatos = candidatos.slice(0, 6);

const terminoCAF = (() => {
  const ts = q.split(/\s+/).filter(Boolean);
  return ts.find(t => t.length >= 4 && !/^\d/.test(t)) || ts.find(t => t.length >= 3) || q;
})();

if (!candidatos.length) {
  const criterios = [];
  if (familiaSolicitada) criterios.push('tipo **' + familiaSolicitada.nombre + '**');
  if (tamanoSolicitado) criterios.push('diámetro **' + tamanoSolicitado + ' pulgadas**');
  if (conexionSolicitada) criterios.push('conexión **' + conexionSolicitada.nombre.toLowerCase() + '**');
  if (servicioVapor) criterios.push('servicio de **vapor**');

  return [{
    json: {
      encontrados: false,
      busqueda,
      terminoCAF,
      mensaje:
        'CAF sí devolvió productos del grupo general, pero no encontré una opción que cumpla de forma segura con ' +
        (criterios.length ? criterios.join(', ') : 'las características solicitadas') + '.\n\n' +
        'No voy a proponerte un producto diferente solo por parecerse en la descripción. ' +
        'Si tienes marca, modelo, presión, material o algún otro dato técnico, indícamelo y vuelvo a buscar.'
    }
  }];
}

const lineas = candidatos.map((r,i) => {
  const codigo = limpio(r.codpro || r.codigo || r.code);
  const desc = limpio(r.nombre_prod || r.descripcion || r.descrip || r.nombre);
  const fab = limpio(r.codigo_fabricante || r.cod_fabricante || r.modelo);
  let linea = (i + 1) + '. **' + (desc || 'Producto sin descripción') + '**';
  if (codigo) linea += '\n   Código interno CAF: ' + codigo;
  if (fab) linea += '\n   Código fabricante/modelo: ' + fab;
  return linea;
}).join('\n\n');

return [{
  json: {
    encontrados: true,
    busqueda,
    terminoCAF,
    solicitudOriginal: originales,
    candidatos,
    mensaje:
      'Encontré estas opciones en CAF que coinciden mejor con las características solicitadas:\n\n' +
      lineas + '\n\n' +
      'Todavía no voy a cotizar ninguna automáticamente. Confírmame cuál corresponde. Si todavía no sabes cuál, indícame presión de trabajo, temperatura, material preferido o marca para afinar la selección antes de revisar existencia.'
  }
}];
